/* =========================
   GLOBAL THEME VARIABLES
========================= */
:root {
    --black-main: #0a0a0a;
    --black-card: #121212;
    --black-light: #1a1a1a;

    --gold-main: #D4AF37;
    --gold-dark: #b8962e;
    --gold-light: #f5d76e;

    --text-primary: #ffffff;
    --text-secondary: #cfcfcf;

    --border-dark: #2a2a2a;
}

/* =========================
   BODY + GLOBAL
========================= */
body {
    background-color: var(--black-main);
    color: var(--text-primary);
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    color: var(--gold-main) !important;
}

/* =========================
   CARDS
========================= */
.ng-card,
.widget,
.card,
.ps-stat-card {
    background-color: var(--black-card) !important;
    border: 1px solid var(--border-dark) !important;
    color: var(--text-primary);
}

.ng-card-header,
.ng-card-footer {
    background-color: var(--black-light) !important;
    border-color: var(--border-dark) !important;
}

/* =========================
   TABLES
========================= */
.table,
.table-divided td,
.table-divided th {
    background-color: var(--black-card) !important;
    color: var(--text-primary) !important;
    border-color: var(--border-dark) !important;
}

.table-divided tbody tr {
    box-shadow: none !important;
}

/* =========================
   SEARCH BAR
========================= */
.search-bar,
.ng-search-bar {
    background-color: var(--black-light) !important;
    border-left: 4px solid var(--gold-main) !important;
}

/* =========================
   BUTTONS
========================= */
.ps-btn.primary-btn {
    background-color: var(--gold-main) !important;
    border: none !important;
    color: #000 !important;
}

.ps-btn.primary-btn:hover {
    background-color: var(--gold-dark) !important;
}

.ps-btn.grey-outline-btn {
    background-color: transparent !important;
    border: 1px solid var(--gold-main) !important;
    color: var(--gold-main) !important;
}

.ps-btn.grey-outline-btn:hover {
    background-color: var(--gold-main) !important;
    color: #000 !important;
}

/* =========================
   LINKS
========================= */
a {
    color: var(--gold-main);
}

a:hover {
    color: var(--gold-light);
}

/* =========================
   NAV TABS
========================= */
.nav-tabs .nav-link {
    color: var(--text-secondary) !important;
}

.nav-tabs .nav-link.active {
    color: var(--gold-main) !important;
}

.nav-tabs .nav-link.active::after {
    background: var(--gold-main) !important;
}

/* =========================
   INPUT FIELDS
========================= */
input,
select,
textarea {
    background-color: var(--black-light) !important;
    border: 1px solid var(--border-dark) !important;
    color: var(--text-primary) !important;
}

input:focus,
select:focus,
textarea:focus {
    border-color: var(--gold-main) !important;
    box-shadow: 0 0 5px rgba(212, 175, 55, 0.4);
}

/* =========================
   POPUP / TOOLTIP
========================= */
.popover {
    background-color: var(--black-card) !important;
    color: var(--text-primary) !important;
}

.popover-header {
    background-color: var(--black-light) !important;
    color: var(--gold-main) !important;
}

/* =========================
   SCROLLBAR (Premium Look)
========================= */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-track {
    background: var(--black-main);
}

::-webkit-scrollbar-thumb {
    background: var(--gold-main);
    border-radius: 10px;
}

/* =========================
   BADGES / STATUS COLORS
========================= */
.greenText {
    color: #00c853 !important;
}

.redText {
    color: #ff5252 !important;
}

.yellowText {
    color: var(--gold-main) !important;
}

/* =========================
   CUSTOM GOLD GLOW EFFECT
========================= */
.gold-glow {
    box-shadow: 0 0 10px rgba(212, 175, 55, 0.5);
}

/* =========================
   HOVER EFFECTS
========================= */
.ng-card:hover,
.widget:hover {
    border-color: var(--gold-main) !important;
    transform: translateY(-2px);
    transition: 0.3s;
}

